examples.setupTemplate:
@Composable
fun RailDivider() = Box(
    Modifier
        .width(MonarchTheme.spacing.space6)
        .height(MonarchTheme.spacing.px)
        .background(MonarchTheme.colors.accentSolidHover),
)
@Composable
fun RailButton(
    icon: ImageVector,
    label: String,
    selected: Boolean = false,
    badge: Boolean = false,
    note: String? = null,
    onClick: () -> Unit = {},
) {
    Box(
        modifier = Modifier
            .size(MonarchTheme.spacing.space10)
            .background(
                if (selected) MonarchTheme.colors.accentSolidActive else Color.Transparent,
                MonarchTheme.shapes.md,
            )
            .clickable(role = Role.Button, onClick = onClick)
            .semantics {
                contentDescription = label
                if (note != null) stateDescription = note
                this.selected = selected
            },
        contentAlignment = Alignment.Center,
    ) {
        Icon(icon, contentDescription = null, tint = MonarchTheme.colors.accentOnSolid)
        if (badge) {
            Box(
                Modifier
                    .align(Alignment.TopEnd)
                    .padding(MonarchTheme.spacing.space1)
                    .size(MonarchTheme.spacing.space2)
                    .background(MonarchTheme.colors.accentOnSolid, CircleShape)
                    .clearAndSetSemantics { },
            )
        }
    }
}
var current by rememberSaveable { mutableStateOf({{current}}) }
var supportOpen by rememberSaveable { mutableStateOf(false) }
val destinations = listOf({{items.0.key}} to {{items.0.label}}, {{items.1.key}} to {{items.1.label}}, {{items.2.key}} to {{items.2.label}})
val icons = mapOf({{items.0.key}} to SampleIcons.Home, {{items.1.key}} to SampleIcons.Inbox, {{items.2.key}} to SampleIcons.Calendar)
val unread = mapOf({{items.1.key}} to {{items.1.badge}})

